CREATE TYPE public.care_role AS ENUM ('admin', 'member');
CREATE TABLE public.care_members (email text PRIMARY KEY CHECK (email = lower(email)), role public.care_role NOT NULL DEFAULT 'member');
GRANT SELECT ON public.care_members TO authenticated;
GRANT ALL ON public.care_members TO service_role;
ALTER TABLE public.care_members ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.care_has_access(admin_only boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.care_members WHERE email = lower(auth.jwt()->>'email') AND (NOT admin_only OR role = 'admin')); $$;
REVOKE ALL ON FUNCTION public.care_has_access(boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.care_has_access(boolean) TO authenticated;
CREATE POLICY members_read ON public.care_members FOR SELECT TO authenticated USING (email = lower(auth.jwt()->>'email') OR public.care_has_access(true));
CREATE TABLE public.care_state (id boolean PRIMARY KEY DEFAULT true CHECK(id), data jsonb NOT NULL DEFAULT '{"customers":[],"pets":[],"services":[],"bookings":[],"capacity":{"spa":8,"boarding":10}}', version integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.care_state TO authenticated;
GRANT ALL ON public.care_state TO service_role;
ALTER TABLE public.care_state ENABLE ROW LEVEL SECURITY;
CREATE POLICY team_read ON public.care_state FOR SELECT TO authenticated USING (public.care_has_access());
CREATE FUNCTION public.care_read() RETURNS SETOF public.care_state LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT public.care_has_access() THEN RAISE EXCEPTION 'Bạn chưa được duyệt vào nhóm'; END IF; INSERT INTO public.care_state(id) VALUES(true) ON CONFLICT DO NOTHING; RETURN QUERY SELECT * FROM public.care_state; END; $$;
CREATE FUNCTION public.care_save(next_data jsonb, expected_version integer) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE updated integer; BEGIN IF NOT public.care_has_access() THEN RAISE EXCEPTION 'Bạn chưa được duyệt vào nhóm'; END IF; UPDATE public.care_state SET data=next_data, version=version+1 WHERE id=true AND version=expected_version RETURNING version INTO updated; IF updated IS NULL THEN RAISE EXCEPTION 'Dữ liệu vừa thay đổi. Vui lòng tải lại rồi thử lại.'; END IF; RETURN updated; END; $$;
REVOKE ALL ON FUNCTION public.care_read() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.care_save(jsonb, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.care_read() TO authenticated;
GRANT EXECUTE ON FUNCTION public.care_save(jsonb, integer) TO service_role;
CREATE FUNCTION public.care_manage_member(member_email text, remove_member boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT public.care_has_access(true) THEN RAISE EXCEPTION 'Chỉ quản lý được thay đổi thành viên'; END IF; IF lower(member_email)=lower(auth.jwt()->>'email') THEN RAISE EXCEPTION 'Không thể xoá quyền của chính bạn'; END IF; IF remove_member THEN DELETE FROM public.care_members WHERE email=lower(member_email) AND role='member'; ELSE INSERT INTO public.care_members(email,role) VALUES(lower(trim(member_email)),'member') ON CONFLICT DO NOTHING; END IF; END; $$;
REVOKE ALL ON FUNCTION public.care_manage_member(text, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.care_manage_member(text, boolean) TO authenticated;